INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(2801, 'Leviticus 7:5', 'Leviticus', 7, 5, '&nbsp;اِمام به هغه ټول مالِک خُدائ ته په اور سوزېدونکې نذرانې په توګه په قربان‌ګاه وسوزوى. دا د ګناه د تاوان نذرانه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2802, 'Leviticus 7:6', 'Leviticus', 7, 6, '&nbsp;د اِمامانو د کورَنو هر نر کس دا خوړلے شى، خو دا به خامخا په يو مقدس ځائ کښې خوړلے شى، ځکه چې دا ډېره مقدسه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2803, 'Leviticus 7:7', 'Leviticus', 7, 7, '&nbsp;د ګناه نذرانې او د ګناه د تاوان نذرانې دواړو دپاره يو شان اصُول دى، غوښه د هغه اِمام ده چې کفاره ادا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2804, 'Leviticus 7:8', 'Leviticus', 7, 8, '&nbsp;اِمام چې د چا دپاره سوزېدونکې نذرانه پېش کوى نو د هغه ځناور څرمن به د هغه اِمام وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2805, 'Leviticus 7:9', 'Leviticus', 7, 9, '&nbsp;د غلې هره يوه نذرانه کومه چې په تنور کښې يا لوښى يا په تبخى پخيږى هغه د اِمام ده چا چې خُدائ پاک ته دا پېش کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2806, 'Leviticus 7:10', 'Leviticus', 7, 10, '&nbsp;خو د غلې هغه ټولې نذرانې چې پخې شوې نۀ وى، کۀ په تېلو غوړې وى يا سپورې وى، هغه د هارون د خاندان د ټولو اِمامانو دى او يو برابر دې په هغوئ باندې وويشلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2807, 'Leviticus 7:11', 'Leviticus', 7, 11, '&nbsp;دا د سلامتۍ د نذرانو دپاره اصُول دى کومې چې مالِک خُدائ ته پېش کولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2808, 'Leviticus 7:12', 'Leviticus', 7, 12, '&nbsp;کۀ يو کس دا نذرانه د شکرانې په توګه خُدائ پاک ته پېش کوى، چې کوم ځناور قربانى کيږى د هغې سره دې په يو ځائ د پتيرې روټۍ يوه نذرانه پېش کړى، داسې غټه روټۍ چې د زيتُونو تېل ورسره ګډ شوى وى يا نرۍ پخې شوې روټۍ چې د زيتُونو تېل ورباندې لګولے شوى وى يا د ښو اوړو نه پخه شوې داسې روټۍ چې د زيتُونو تېل ورسره ګډ شوى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2809, 'Leviticus 7:13', 'Leviticus', 7, 13, '&nbsp;د دې نه علاوه، هغه دې خمبيره پخې شوې روټۍ هم پېش کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2810, 'Leviticus 7:14', 'Leviticus', 7, 14, '&nbsp;هغه دې د هر قِسم روټۍ يوه يوه حِصه د خاص برخې په توګه مالِک خُدائ ته پېش کړى، دا د هغه اِمام دى کوم چې د ځناور وينه واخلى او د قربان‌ګاه سره يې وشيندى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2811, 'Leviticus 7:15', 'Leviticus', 7, 15, '&nbsp;د سلامتۍ د نذرانې غوښه دې خامخا هم په هغه ورځ وخوړلے شى چې په کومه ورځ هغه قربانى کيږى، تر بل سحر پورې دې د هغې نه هيڅ څيز پاتې نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2812, 'Leviticus 7:16', 'Leviticus', 7, 16, '&nbsp;کۀ يو کس د قسم پوره کولو يا د خپلې رضاکارانه نذرانې په توګه، د سلامتۍ نذرانه راوړى، چې دا په کومه ورځ پېش کيږى نو په هغه ورځ دې خوړلے شى خو چې څۀ پاتې وى نو هغه به په بله ورځ خوړلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2813, 'Leviticus 7:17', 'Leviticus', 7, 17, '&nbsp;څۀ غوښه چې پاتې وى نو هغه دې په درېمه ورځ وسوزولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2814, 'Leviticus 7:18', 'Leviticus', 7, 18, '&nbsp;کۀ د سلامتۍ نذرانې نه څۀ په درېمه ورځ هم وخوړلے شى، نو خُدائ پاک به د هغه کس نذرانه قبوله نۀ کړى. دا نذرانه به د هغۀ په فائده کښې حِساب نۀ شى بلکې ناپاکه به وګڼلے شى او چې څوک هم دا وخورى نو هغۀ ته به د خپلو بدو سزا مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2815, 'Leviticus 7:19', 'Leviticus', 7, 19, '&nbsp;کۀ چرې دا غوښه په يو ناپاک څيز پورې ولګى، نو دا دې نۀ شى خوړلے، بلکې ودې سوزولے شى. چې څوک پاک وى نو هغه دا پاتې شوې غوښه خوړلے شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2816, 'Leviticus 7:20', 'Leviticus', 7, 20, '&nbsp;خو کۀ څوک پاک نۀ وى او د سلامتۍ نذرانې غوښه وخورى کومه چې مالِک خُدائ ته پېش کړے شوې وى، نو هغه به نور د خُدائ پاک د خلقو نه نۀ شى ګڼلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2817, 'Leviticus 7:21', 'Leviticus', 7, 21, '&nbsp;کۀ يو کس ناپاک څيز له لاس وروړى، کۀ هغه ناپاکى د بنى آدم يا د ځناور وى او د دې نذرانې غوښه وخورى، نو هغه به نور د مالِک خُدائ د خلقو نه نۀ شى ګڼلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2818, 'Leviticus 7:22', 'Leviticus', 7, 22, '&nbsp;مالِک خُدائ موسىٰ ته دا اصُول وښودل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2819, 'Leviticus 7:23', 'Leviticus', 7, 23, '&nbsp;کوم چې د بنى اِسرائيلو دپاره دى، د څاروو، ګډو، يا د چېلو وازګه مۀ خورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2820, 'Leviticus 7:24', 'Leviticus', 7, 24, '&nbsp;يو ځناور چې په خپل مرګ مړ وى يا کۀ ځنګلى ځناورو وژلے وى د هغۀ وازګه به نۀ خورئ، خو هغه د څۀ بل مقصد دپاره استعمالېدے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2821, 'Leviticus 7:25', 'Leviticus', 7, 25, '&nbsp;کۀ څوک د يو ځناور وازګه وخورى کوم چې مالِک خُدائ ته په اور سوزېدونکې نذرانې په توګه پېش کېدے شوه نو هغه کس به نور د خُدائ پاک د خلقو نه نۀ شى ګڼلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2822, 'Leviticus 7:26', 'Leviticus', 7, 26, '&nbsp;بنى اِسرائيل چې چرته هم اوسيږى، هغوئ دې هيڅکله هم د مارغانو يا د ځناورو وينه نۀ خورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2823, 'Leviticus 7:27', 'Leviticus', 7, 27, '&nbsp;هر څوک چې وينه وخورى نو هغه به نور د خُدائ پاک د خلقو نه نۀ شى ګڼلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2824, 'Leviticus 7:28', 'Leviticus', 7, 28, '&nbsp;بيا مالِک خُدائ موسىٰ ته دا اصُول وښودل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2825, 'Leviticus 7:29', 'Leviticus', 7, 29, '&nbsp;کوم چې د بنى اِسرائيلو دپاره دى. هر څوک چې يوه د سلامتۍ نذرانه پېش کوى نو د هغې يوه برخه به د خاص تُحفې په توګه مالِک خُدائ ته پېش کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2826, 'Leviticus 7:30', 'Leviticus', 7, 30, '&nbsp;هغه دې دا په خپلو لاسونو په اور سوزېدونکې نذرانې په توګه راوړى. هغه دې د هغه ځناور وازګه سره د ځناور د سينې راوړى او مالِک خُدائ ته دې د يو خاص تُحفې په توګه پېش کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2827, 'Leviticus 7:31', 'Leviticus', 7, 31, '&nbsp;اِمام به وازګه په قربان‌ګاه باندې وسوزوى، خو هغه سينه به د اِمامانو وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2828, 'Leviticus 7:32', 'Leviticus', 7, 32, '&nbsp;د ځناور وروستونے ښے پتُون به د يوې برخې په توګه اِمام ته ورکولے شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2829, 'Leviticus 7:33', 'Leviticus', 7, 33, '&nbsp;هغه اِمام له کوم چې وينه او د سلامتۍ نذرانې وازګه پېش کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2830, 'Leviticus 7:34', 'Leviticus', 7, 34, '&nbsp;د ځناور سينه يوه خاص تُحفه ده او ښے پتُون يوه خاص برخه ده چې مالِک خُدائ يې د بنى اِسرائيلو نه اخلى او اِمامانو له يې ورکوى. نو داسې به اِسرائيليان په راتلونکى ټولو وختونو کښې دا اِمامانو له ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2831, 'Leviticus 7:35', 'Leviticus', 7, 35, '&nbsp;دا مالِک خُدائ ته په اور سوزېدونکې نذرانې برخه ده چې هارون او د هغۀ زامنو له ورکړے شوه چې په کومه ورځ هغوئ د اِمامانو په توګه مقرر شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2832, 'Leviticus 7:36', 'Leviticus', 7, 36, '&nbsp;مالِک خُدائ په هغه ورځ چې کله هغوئ په تېلو سره مسح کړل حکم ورکړے وو چې بنى اِسرائيل به دا برخه همېشه اِمامانو له ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2833, 'Leviticus 7:37', 'Leviticus', 7, 37, '&nbsp;دا اصُول د سوزېدونکې نذرانو دپاره دى، د غلې نذرانو دپاره، د ګناه نذرانو، د ګناه د تاوان د نذرانو، د مقررولو نذرانو او د سلامتۍ د نذرانو دپاره دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2834, 'Leviticus 7:38', 'Leviticus', 7, 38, '&nbsp;هلته په بيابان کښې د سينا په غرۀ باندې، مالِک خُدائ په هغه ورځ موسىٰ له دا حُکمونه ورکړل او هغۀ بنى اِسرائيلو ته وفرمائيل چې خپلې نذرانې راوړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2835, 'Leviticus 8:1', 'Leviticus', 8, 1, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2836, 'Leviticus 8:2', 'Leviticus', 8, 2, '&nbsp;”هارون او د هغۀ زامن او د اِمامانو لِباس، د غوړولو تېل، د ګناه نذرانې دپاره سخے، دوه ګډان او د پتيرې روټۍ ټوکرۍ راوړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2837, 'Leviticus 8:3', 'Leviticus', 8, 3, '&nbsp;او زما د حضور مقدسې خېمې د دروازې خولې ته ټول قوم راوغواړه چې هلته راغونډ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2838, 'Leviticus 8:4', 'Leviticus', 8, 4, '&nbsp;موسىٰ هم هغه شان وکړل چې څنګه مالِک خُدائ حُکم ورکړے وو او چې کله ټول قوم هلته راغونډ شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2839, 'Leviticus 8:5', 'Leviticus', 8, 5, '&nbsp;نو موسىٰ هغوئ ته وفرمائيل، ”زۀ چې څۀ کوم مالِک خُدائ د دې حُکم راکړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2840, 'Leviticus 8:6', 'Leviticus', 8, 6, '&nbsp;موسىٰ هارون او د هغۀ زامن مخکښې راوستل او هغوئ له يې په اوبو غسل ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2841, 'Leviticus 8:7', 'Leviticus', 8, 7, '&nbsp;هغۀ هارون ته هغه قميص او چُوغه ورواغوستله او د ملا نه يې پټۍ ورله تاو کړه. هغه پېش بند يې ورواغوستلو او په يو ښۀ ګُلکارى شوى کمربند سره يې ونښلولو چې د هغۀ د ملا نه تاو وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2842, 'Leviticus 8:8', 'Leviticus', 8, 8, '&nbsp;هغۀ ورله د سينې جېب ولګولو او اُوريم او تميم يې په کښې کېښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2843, 'Leviticus 8:9', 'Leviticus', 8, 9, '&nbsp;هارون ته يې پټکے ورپه سر کړو او د دې مخې ته يې د سرو زرو ګل ولګولو چې دا د وقف کولو مقدسه نښه وه، هم هغه شان چې څنګه مالِک خُدائ هغۀ ته حُکم ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2844, 'Leviticus 8:10', 'Leviticus', 8, 10, '&nbsp;بيا موسىٰ د غوړولو تېل واخستل او د مالِک خُدائ د حضور په مقدسه خېمه او چې په هغې کښې څۀ هم وُو په هغې باندې يې ولګول، نو هغۀ دا هر څۀ مالِک خُدائ ته مخصوص کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2845, 'Leviticus 8:11', 'Leviticus', 8, 11, '&nbsp;هغۀ څۀ تېل اووۀ ځله په قربان‌ګاه، د دې په سامان او د وينځلو په ښانک او د دې په بېخ باندې وشيندل، د دې دپاره چې دا مالِک خُدائ ته وقف کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2846, 'Leviticus 8:12', 'Leviticus', 8, 12, '&nbsp;موسىٰ د هارون په سر باندې د غوړولو دپاره څۀ تېل واچول او سر يې ورله غوړ کړو چې وقف شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2847, 'Leviticus 8:13', 'Leviticus', 8, 13, '&nbsp;بيا، موسىٰ د هارون زامن مخکښې راوستل او قميصونه يې ورواغوستل، د هغوئ د ملا نه يې پټۍ تاو کړې او ټوپۍ يې ورپه سر کړې، هم هغه شان چې څنګه مالِک خُدائ حُکم ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2848, 'Leviticus 8:14', 'Leviticus', 8, 14, '&nbsp;بيا موسىٰ د ګناه د نذرانې دپاره هغه سخے راوستو او هارون او د هغۀ زامنو د دې په سر باندې خپل لاسونه کېښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
