(2889, 'Leviticus 9:21', 'Leviticus', 9, 21, '&nbsp;او هغه سينې او ښے پتُون يې مالِک خُدائ ته د اِمامانو دپاره د خاص تُحفې په توګه پېش کړې، څنګه چې موسىٰ حُکم کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2890, 'Leviticus 9:22', 'Leviticus', 9, 22, '&nbsp;چې کله هارون ټولې قربانۍ ختمې کړې، هغۀ خپل لاسونه د خلقو طرف ته اوږدۀ کړل او د هغوئ دپاره يې برکت وغوښتو او بيا راکوز شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2891, 'Leviticus 9:23', 'Leviticus', 9, 23, '&nbsp;موسىٰ او هارون د مالِک خُدائ مقدسې خېمې ته دننه لاړل او چې راووتل، نو د خلقو دپاره يې برکت وغوښتلو او د مالِک خُدائ جلال ټولو خلقو ته څرګند شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2892, 'Leviticus 9:24', 'Leviticus', 9, 24, '&nbsp;ناڅاپه مالِک خُدائ اور راولېږلو او دې اور په قربان‌ګاه باندې د وازګې والا حِصې او سوزېدونکې نذرانه پوره وسوزوله. چې خلقو دا وليدل، نو هغوئ ټولو چغې کړې او سجده يې وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2893, 'Leviticus 10:1', 'Leviticus', 10, 1, '&nbsp;نو د هارون زامنو ندب او ابيهُو، هر يو خپل مجمر واخستلو او ژوندى سکارۀ يې په کښې واچول، خوشبوئى يې ورباندې واچوله او دا يې مالِک خُدائ ته پېش کړل. خو دا اور خُدائ پاک ته قبول نۀ وو، ځکه چې مالِک خُدائ هغوئ له د دې د پېش کولو حُکم نۀ وو ورکړے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2894, 'Leviticus 10:2', 'Leviticus', 10, 2, '&nbsp;نو ناڅاپه مالِک خُدائ اور راولېږلو او دې اور هلته د مالِک خُدائ په حضور کښې هغوئ وسوزول او مړۀ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2895, 'Leviticus 10:3', 'Leviticus', 10, 3, '&nbsp;بيا موسىٰ هارون ته وفرمائيل، ”د مالِک خُدائ مطلب دا وو کله چې هغۀ وفرمائيل، هر څوک چې زما خِدمت کوى هغوئ دې خامخا زما د پاکوالى عزت کوى، زۀ به خپلو خلقو ته خپل جلال څرګند کړم.“ خو هارون غلے پاتې شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2896, 'Leviticus 10:4', 'Leviticus', 10, 4, '&nbsp;موسىٰ ميسائيل او الصفن، د عُزى‌اېل زامن راوغوښتل، عُزى‌اېل د هارون ترۀ وو او موسىٰ هغوئ ته وفرمائيل، ”دلته راشئ او د خپل ترۀ د زامنو مړى د مقدسې خېمې نه يوسئ او د کېمپ نه بهر يې کېږدئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2897, 'Leviticus 10:5', 'Leviticus', 10, 5, '&nbsp;نو هغوئ راغلل او مړى يې د جامو نه ونيول او د خېمو نه بهر يې يوړل، هم هغه شان چې څنګه موسىٰ حُکم ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2898, 'Leviticus 10:6', 'Leviticus', 10, 6, '&nbsp;بيا موسىٰ هارون او د هغۀ زامنو اِلى‌عزر او اِتمر ته وفرمائيل، ”خپل وېښتۀ ببر مۀ ساتئ او نۀ چې خپلې جامې وشلوئ چې ښکاره کړئ چې په غم غمژن يئ. کۀ تاسو داسې وکړل، نو مړۀ به شئ. او مالِک خُدائ به ټول قوم ته په قهر شى. خو نورو بنى اِسرائيلو ته اجازت دے چې په دې غم غمژن شى کوم مرګ چې د مالِک خُدائ د اور په وجه شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2899, 'Leviticus 10:7', 'Leviticus', 10, 7, '&nbsp;د مقدسې خېمې د دروازې د خولې نه مۀ ځئ ګنې مړۀ به شئ، ځکه چې تاسو د مالِک خُدائ په تېلو غوړ کړے شوى يئ.“ نو هغوئ هم هغه شان وکړل چې څنګه موسىٰ فرمائيلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2900, 'Leviticus 10:8', 'Leviticus', 10, 8, '&nbsp;نو مالِک خُدائ هارون ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');